# 화면 순서는 CARDS에 적힌 순서다(dash_common.sections). 회사 먼저, 그다음 회사 밖.
# 회사가 늘어나므로 순서를 손으로 나열하지 않는다 — SEC_ORDER에 섹션을 더하면 된다.
# 회사 밖 이야기는 언제나 맨 뒤다.
# 타일에 붙는 괴리 배지 — 그 회사의 **가장 최근** 평가가 그 글의 비교 주가보다 몇 % 위/아래인가.
# 툴팁 맨 앞 날짜는 **평가 시점**이다(화면에 뜨는 날짜이자 3개월 창을 가르는 기준).
# 견준 주가의 날짜가 그와 다르면 뒤 문장에 따로 적는다 — 글보다 하루 이틀 앞선 종가를
# 쓰는 편이 있어 둘을 한 자리에 두면 어느 날 값인지가 섞인다.
# 값은 전부 원문이 낸 것이고 여기서 다시 계산하지 않는다.
# 기준 시점과 시장은 편마다 다르다(종가·장중·장전·KRX 기준가·NXT). 그래서 툴팁에 무엇과
# 견준 값인지를 같이 적는다 — 배지 숫자만 보면 서로 다른 시점을 견주게 된다.
# 역산 편은 값을 내지 않으므로 숫자를 만들지 않고 방법 이름만 회색으로 단다.
